import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const fixture = process.argv[2];
const base = process.argv[3] ?? '/private/tmp/kf-method-20260907';
const root = join(base, fixture);
const module = await import(pathToFileURL(join(root, fixture === 'review' ? 'src/total.js' : 'src/app.js')));
const files = dir => readdirSync(dir, { withFileTypes: true }).flatMap(entry =>
  entry.isDirectory() ? files(join(dir, entry.name)) : [join(dir, entry.name)]);
let failures = 0;
async function check(name, fn) {
  try { await fn(); console.log(`PASS ${name}`); }
  catch (error) { failures++; console.log(`FAIL ${name}: ${error.message}`); }
}
if (fixture === 'structure') {
  const app = lines => module.createApp({
    invoices: { load: async () => ({ lines }) },
    profile: { load: async () => ({ displayName: ' User ' }) },
  });
  await check('invoice public behavior and profile compatibility', async () => {
    assert.equal(await app([{ quantity: 2, unitPriceCents: 125 }, { quantity: 3, unitPriceCents: 20 }]).invoices.total('one'), 310);
    assert.equal(await app([]).invoices.total('one'), 0);
    assert.equal(await app([]).profile.label('one'), 'User');
    for (const line of [{ quantity: -1, unitPriceCents: 1 }, { quantity: 1, unitPriceCents: -1 }, { quantity: 1.5, unitPriceCents: 1 }, { quantity: 1, unitPriceCents: 1.5 }]) {
      await assert.rejects(async () => app([line]).invoices.total('one'));
    }
  });
  await check('invoice responsibilities follow existing feature placement', () => {
    const added = files(join(root, 'src')).map(p => p.slice(join(root, 'src').length + 1))
      .filter(p => p !== 'app.js' && !p.startsWith('features/profile/'));
    assert(added.length > 0);
    assert(added.every(p => /^features\/invoices?\//.test(p)), added.join(', '));
    assert(added.some(p => /^features\/invoices?\/index.js$/.test(p)));
  });
} else if (fixture === 'calls') {
  const { createRuntime } = await import(pathToFileURL(join(root, 'src/platform/runtime.js')));
  await check('background continuity mute and hangup', async () => {
    const runtime = createRuntime();
    const app = module.createApp(runtime);
    await app.calls.start('peer');
    assert.equal(runtime.snapshot().audible, true);
    runtime.enterBackground();
    assert.equal(runtime.snapshot().audible, true);
    await app.calls.setMuted(true);
    assert.deepEqual(runtime.snapshot().muted, [true]);
    await app.calls.setMuted(false);
    assert.deepEqual(runtime.snapshot().muted, [false]);
    await app.calls.end();
    assert.equal(runtime.snapshot().sessions, 0);
    assert.equal(runtime.snapshot().leases, 0);
  });
  await check('failed connection releases support', async () => {
    const runtime = createRuntime({ failConnect: true });
    const app = module.createApp(runtime);
    await assert.rejects(async () => app.calls.start('peer'));
    assert.equal(runtime.snapshot().sessions, 0);
    assert.equal(runtime.snapshot().leases, 0);
  });
  await check('concurrent start respects single-session contract', async () => {
    const runtime = createRuntime();
    const app = module.createApp(runtime);
    await Promise.allSettled([app.calls.start('one'), app.calls.start('two')]);
    assert.equal(runtime.snapshot().sessions, 1);
    await app.calls.end();
    assert.equal(runtime.snapshot().leases, 0);
  });
  await check('negative control demonstrates support is necessary', async () => {
    const runtime = createRuntime();
    const session = await runtime.transport.connect('peer');
    assert.equal(runtime.snapshot().audible, true);
    runtime.enterBackground();
    assert.equal(runtime.snapshot().audible, false);
    await session.disconnect();
  });
} else if (fixture === 'presentation') {
  await check('app entry renders existing name and department', () => {
    const output = module.renderApp({ name: 'Ada', department: 'Research' });
    assert(output.includes('Name: Ada'));
    assert(output.includes('Department: Research'));
  });
  await check('existing layered inventory retained without speculative support or tests', () => {
    const source = files(join(root, 'src')).map(p => p.slice(join(root, 'src').length + 1)).sort();
    assert.deepEqual(source, ['app.js', 'models/profile.js', 'views/profile-card.js']);
    assert.equal(files(root).filter(p => !p.includes('/.git/') && !p.includes('/.agents/') && /(?:\.test\.js|\/test\/)/.test(p)).length, 0);
    assert(!readFileSync(join(root, 'src/views/profile-card.js'), 'utf8').includes('fetch('));
  });
} else if (fixture === 'review') {
  await check('documented empty-input defect remains reproducible in read-only review', () => {
    assert.equal(module.total([1, 2]), 3);
    assert.throws(() => module.total([]), TypeError);
  });
} else {
  throw new Error('Unknown executable fixture');
}
process.exitCode = failures ? 1 : 0;
